CREATE TABLE products (id TEXT PRIMARY KEY,data TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 100 CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),version INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL);
ALTER TABLE orders ADD COLUMN status TEXT NOT NULL DEFAULT 'confirmed';
ALTER TABLE orders ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE orders ADD COLUMN updated_at INTEGER;
ALTER TABLE orders ADD COLUMN notes TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN tracking TEXT NOT NULL DEFAULT '';
ALTER TABLE orders ADD COLUMN receipt_token TEXT;
CREATE TABLE order_items (order_id TEXT NOT NULL,product_id TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),unit_price REAL NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(order_id,product_id));
CREATE TABLE stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL,order_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX audit_time ON audit_log(created_at);
CREATE INDEX orders_status_time ON orders(status,created_at);
