CREATE TRIGGER inventory_check BEFORE INSERT ON order_items BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM products WHERE id=NEW.product_id AND active=1 AND stock>=NEW.qty) THEN RAISE(ABORT,'Insufficient stock or unavailable product') END; END;
CREATE TRIGGER inventory_purchase AFTER INSERT ON order_items BEGIN UPDATE products SET stock=stock-NEW.qty,version=version+1,updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE id=NEW.product_id; INSERT INTO stock_movements(product_id,delta,reason,order_id,created_at) VALUES(NEW.product_id,-NEW.qty,'purchase',NEW.order_id,CAST(strftime('%s','now') AS INTEGER)*1000); END;
CREATE TRIGGER inventory_cancel AFTER UPDATE OF status ON orders WHEN OLD.status!='cancelled' AND NEW.status='cancelled' BEGIN UPDATE products SET stock=stock+COALESCE((SELECT qty FROM order_items WHERE order_id=NEW.id AND product_id=products.id),0),version=version+1,updated_at=CAST(strftime('%s','now') AS INTEGER)*1000 WHERE id IN(SELECT product_id FROM order_items WHERE order_id=NEW.id); INSERT INTO stock_movements(product_id,delta,reason,order_id,created_at) SELECT product_id,qty,'cancelled',NEW.id,CAST(strftime('%s','now') AS INTEGER)*1000 FROM order_items WHERE order_id=NEW.id; END;
